import os
from pathlib import Path

code_path = Path('{{var.code_file_path}}')
max_size = {{var.max_file_size}} * 1024

code_files = []

if code_path.is_file():
    if code_path.stat().st_size <= max_size:
        code_files.append(str(code_path))
    else:
        print(f'文件过大，跳过：{code_path}')
elif code_path.is_dir():
    for root, dirs, files in os.walk(code_path):
        # 跳过常见的无需分析的目录
        dirs[:] = [d for d in dirs if d not in ['.git', 'node_modules', '__pycache__', 'venv', 'dist', 'build']]

        for file in files:
            file_path = Path(root) / file
            # 只处理代码文件
            if file_path.suffix in ['.py', '.js', '.ts', '.java', '.go', '.rs', '.cpp', '.c', '.h']:
                if file_path.stat().st_size <= max_size:
                    code_files.append(str(file_path))
                else:
                    print(f'文件过大，跳过：{file_path}')
else:
    raise ValueError(f'路径不存在：{code_path}')

print(f'找到 {len(code_files)} 个代码文件')
context['code_files'] = code_files
context['total_count'] = len(code_files)

from datetime import datetime

code_files = context.get('code_files', [])
analysis_results = context.get('analysis_results', [])

report = f'''# 代码质量分析报告

**分析时间**：{datetime.now().strftime('%Y-%m-%d %H:%M:%S')}
**分析文件数**：{len(code_files)}
**分析重点**：{{var.analysis_focus}}

---

'''

for file_path, result in zip(code_files, analysis_results):
    report += f'''## 文件：{file_path}

{result}

---

'''

context['report'] = report
print('分析报告生成完成')
